int longestSubstring(string s) {
    int n = s.length(), maxLen = 0;
    unordered_set<char> st;
    int l = 0;
    for(int r = 0; r < n; r++) {
        while(st.count(s[r])) { st.erase(s[l]); l++; }
        st.insert(s[r]);
        maxLen = max(maxLen, r - l + 1);
    }
    return maxLen;
}

