vector<int> patternMatch(string text, string pattern) {
    vector<int> res;
    int n = text.length(), m = pattern.length();
    for(int i = 0; i <= n - m; i++) {
        int j;
        for(j = 0; j < m; j++)
            if(text[i+j] != pattern[j]) break;
        if(j == m) res.push_back(i);
    }
    return res;
}

